import app from 'flarum/forum/app';
import { extend } from 'flarum/common/extend';
import Switch from 'flarum/common/components/Switch';
import FieldSet from 'flarum/common/components/FieldSet';

/** "Друзья" section on the user's own Settings page — one toggle per badge, each only shown where the matching admin-wide toggle is on. */
export default function addFriendUserSettings() {
  extend('flarum/forum/components/SettingsPage', 'settingsItems', function (items) {
    const user = this.user;
    if (!user) return;
    const showOnUserCardAllowed = app.forum.attribute('friendshipShowBadgeOnUserCard') !== false;
    const showInPostsAllowed = app.forum.attribute('friendshipShowBadgeOnPost') !== false;
    if (!showOnUserCardAllowed && !showInPostsAllowed) return;
    const prefs = user.preferences?.() ?? {};
    const showOnUserCard = prefs['friendshipShowOnUserCard'] !== false;
    const showInPosts = prefs['friendshipShowInPosts'] !== false;
    items.add('friendship', m(FieldSet, {
      className: "FriendshipSettings",
      label: app.translator.trans('forumaker-friendship.forum.settings.section_label')
    }, showOnUserCardAllowed && m(Switch, {
      state: showOnUserCard,
      onchange: value => user.savePreferences({
        friendshipShowOnUserCard: value
      })
    }, app.translator.trans('forumaker-friendship.forum.settings.show_on_usercard')), showInPostsAllowed && m(Switch, {
      state: showInPosts,
      onchange: value => user.savePreferences({
        friendshipShowInPosts: value
      })
    }, app.translator.trans('forumaker-friendship.forum.settings.show_in_posts'))), -10);
  });
}